type Pulse = {
  episode: {
    state: string;
    current: boolean;
    changedSince: string[];
    conclusion: { intent: string; conclusionId: string } | null;
    readiness: { deliveryBlockers: string[]; awaitingOperator: string[]; mechanicalActions: string[] };
    detail: string;
  };
  openQuestions: Array<{ title: string }>;
