};

type Readiness = {
  action: string;
  reasons: string[];
  next: string[];
  task: unknown;
  attempt: unknown;
  directOutcome: {
    repositoryHead: string | null;
    projectHead: string;
    relation: string;
    uncommittedPaths: string[];
  } | null;
};

it("points a taskless project at its direct commit, then at the recorded conclusion", async () => {
  const { repo, head, stateDir } = workspace("direct-readiness");
  const installed = install(repo, stateDir);
  await start(installed, head, []);
  const read = async () => (await call(installed, "palimpsest_work", { action: "readiness" })) as unknown as Readiness;
  const offersDeliver = (value: Readiness) => value.next.some((line) => /intent=DELIVER/u.test(line));

  const initial = await read();
  expect(initial.action).toBe("CONTINUE_WORK");
  expect(offersDeliver(initial)).toBe(false);

  writeFileSync(join(repo, "docs", "result.md"), "# A real uncommitted draft\n");
  const dirty = await read();
  expect(dirty.action).toBe("CONTINUE_WORK");
  expect(dirty.directOutcome?.uncommittedPaths).toContain("docs/result.md");
  expect(offersDeliver(dirty)).toBe(false);

  execFileSync("git", ["add", "-A"], { cwd: repo });
  execFileSync("git", ["-c", "user.email=t@t.t", "-c", "user.name=t", "commit", "-qm", "direct result"], { cwd: repo });
  const direct = execFileSync("git", ["rev-parse", "HEAD"], { cwd: repo, encoding: "utf8" }).trim();
  expect(direct).not.toBe(head);

  const committed = await read();
  expect(committed.action).toBe("SEMANTIC_JUDGEMENT");
  expect(committed.task).toBeNull();
  expect(committed.attempt).toBeNull();
  expect(committed.directOutcome).toMatchObject({ repositoryHead: direct, projectHead: head, relation: "DIRECT_AHEAD" });
  expect(committed.reasons.join(" ")).toContain(direct);
  expect(committed.next.join(" ")).toContain("palimpsest_work action=conclude intent=DELIVER");

  const delivered = (await call(installed, "palimpsest_work", {
    action: "conclude",
    intent: "DELIVER",
    statement: "The direct commit is the reviewable result.",
    artifacts: ["docs/result.md"],
  })) as unknown as Conclude;
  expect(delivered.state).toBe("RECORDED");
  expect(delivered.session.mayEnd).toBe(true);

  const after = await read();
  expect(after.action).toBe("SEMANTIC_JUDGEMENT");
  expect(after.next).toEqual(["reply using the recorded conclusion"]);
  expect(offersDeliver(after)).toBe(false);

  // A later uncommitted edit is not hidden by the recorded conclusion.
  writeFileSync(join(repo, "docs", "result.md"), "# An uncommitted revision\n");
  const dirtyAfter = await read();
  expect(dirtyAfter.action).toBe("CONTINUE_WORK");
  expect(offersDeliver(dirtyAfter)).toBe(false);

  expect(installed.controller.status()).toMatchObject({ headCommit: head, attempts: [], promotions: [] });
});

